/* AVTO ONLINE - CORE ENGINE WITH FULL 1240 OSON PRAVA QUESTIONS */

let currentLang = 'uz'; // 'uz' or 'ru'
let activeQuizQuestions = [];
let currentQIdx = 0;
let userStats = { solved: 0, correct: 0, wrong: 0 };
let examTimer = null;
let timeLeft = 900; // 15 mins

// Initialize app when DOM is ready
document.addEventListener('DOMContentLoaded', () => {
  renderTickets();
  loadStats();
});

// --- TAB SWITCHING ---
function switchTab(tabId) {
  document.querySelectorAll('.tab-page').forEach(page => page.classList.remove('active'));
  document.querySelectorAll('.tab-item').forEach(item => item.classList.remove('active'));

  document.getElementById(tabId).classList.add('active');
  event.currentTarget.classList.add('active');
}

// --- THEME & LANGUAGE ---
function toggleTheme() {
  document.body.classList.toggle('light-theme');
  const isLight = document.body.classList.contains('light-theme');
  document.getElementById('theme-btn').innerText = isLight ? '☀️' : '🌙';
}

function toggleLanguage() {
  currentLang = currentLang === 'uz' ? 'ru' : 'uz';
  document.getElementById('current-lang-text').innerText = currentLang.toUpperCase();
  renderTickets();
}

// --- RENDER 44 TICKETS (BILETLAR) ---
function renderTickets() {
  const container = document.getElementById('tickets-grid');
  container.innerHTML = '';

  for (let i = 1; i <= 44; i++) {
    const card = document.createElement('div');
    card.className = 'ticket-card';
    card.onclick = () => startTicketSession(i);
    card.innerHTML = `
      <div class="ticket-num">${currentLang === 'uz' ? i + '-Bilet' : 'Билет ' + i}</div>
      <div class="ticket-sub">30 ${currentLang === 'uz' ? 'Savol' : 'Вопросов'}</div>
    `;
    container.appendChild(card);
  }
}

// --- START TICKET SESSION ---
function startTicketSession(ticketNum) {
  const startIndex = (ticketNum - 1) * 28;
  const endIndex = Math.min(startIndex + 28, ALL_QUESTIONS.length);
  
  activeQuizQuestions = ALL_QUESTIONS.slice(startIndex, endIndex);
  if (activeQuizQuestions.length === 0) {
    activeQuizQuestions = ALL_QUESTIONS.slice(0, 20);
  }

  currentQIdx = 0;
  switchTabDirect('exam-tab');
  document.getElementById('exam-start-screen').classList.add('hidden');
  document.getElementById('active-quiz-container').classList.remove('hidden');

  renderQuizQuestion();
}

// --- START EXAM SESSION (RANDOM 20 QUESTIONS) ---
function startExamSession() {
  // Pick 20 random questions
  const shuffled = [...ALL_QUESTIONS].sort(() => 0.5 - Math.random());
  activeQuizQuestions = shuffled.slice(0, 20);

  currentQIdx = 0;
  timeLeft = 900;

  document.getElementById('exam-start-screen').classList.add('hidden');
  document.getElementById('active-quiz-container').classList.remove('hidden');

  startTimer();
  renderQuizQuestion();
}

function switchTabDirect(tabId) {
  document.querySelectorAll('.tab-page').forEach(page => page.classList.remove('active'));
  document.getElementById(tabId).classList.add('active');
}

// --- TIMER ---
function startTimer() {
  clearInterval(examTimer);
  examTimer = setInterval(() => {
    timeLeft--;
    const mins = Math.floor(timeLeft / 60);
    const secs = timeLeft % 60;
    document.getElementById('quiz-timer').innerText = `⏱️ ${mins}:${secs < 10 ? '0' : ''}${secs}`;

    if (timeLeft <= 0) {
      clearInterval(examTimer);
      alert(currentLang === 'uz' ? "Vaqt tugadi!" : "Время вышло!");
      resetExamView();
    }
  }, 1000);
}

// --- RENDER QUIZ QUESTION ---
function renderQuizQuestion() {
  const q = activeQuizQuestions[currentQIdx];
  if (!q) return;

  document.getElementById('q-curr').innerText = currentQIdx + 1;
  document.getElementById('q-total').innerText = activeQuizQuestions.length;
  document.getElementById('quiz-progress-fill').style.width = `${((currentQIdx + 1) / activeQuizQuestions.length) * 100}%`;

  // Question Image
  const imgBox = document.getElementById('q-image-box');
  const img = document.getElementById('q-image');
  if (q.photo) {
    img.src = q.photo;
    imgBox.classList.remove('hidden');
  } else {
    imgBox.classList.add('hidden');
  }

  // Question Text
  document.getElementById('q-text').innerText = q.question[currentLang] || q.question['uz'];

  // Options
  const optionsList = document.getElementById('q-options');
  optionsList.innerHTML = '';
  document.getElementById('q-explanation').classList.add('hidden');

  q.options.forEach((opt, idx) => {
    const btn = document.createElement('button');
    btn.className = 'option-btn';
    btn.innerText = opt[currentLang] || opt['uz'];
    btn.onclick = () => selectOption(btn, opt.correct, q.explanation[currentLang] || q.explanation['uz']);
    optionsList.appendChild(btn);
  });
}

// --- SELECT OPTION ---
function selectOption(btn, isCorrect, explanationText) {
  const allBtns = document.querySelectorAll('.option-btn');
  allBtns.forEach(b => b.onclick = null);

  userStats.solved++;

  if (isCorrect) {
    btn.classList.add('correct');
    userStats.correct++;
  } else {
    btn.classList.add('wrong');
    userStats.wrong++;
  }

  saveStats();

  // Show Explanation
  if (explanationText && explanationText.trim() !== '') {
    document.getElementById('exp-text').innerText = explanationText;
    document.getElementById('q-explanation').classList.remove('hidden');
  } else {
    setTimeout(nextQuestion, 1200);
  }
}

// --- NEXT QUESTION ---
function nextQuestion() {
  currentQIdx++;
  if (currentQIdx >= activeQuizQuestions.length) {
    clearInterval(examTimer);
    alert(currentLang === 'uz' ? "Tabriklaymiz! Test yakunlandi." : "Поздравляем! Тест завершен.");
    resetExamView();
  } else {
    renderQuizQuestion();
  }
}

function resetExamView() {
  document.getElementById('exam-start-screen').classList.remove('hidden');
  document.getElementById('active-quiz-container').classList.add('hidden');
}

// --- STATS MANAGEMENT ---
function saveStats() {
  localStorage.setItem('avto_stats', JSON.stringify(userStats));
  loadStats();
}

function loadStats() {
  const saved = localStorage.getItem('avto_stats');
  if (saved) userStats = JSON.parse(saved);

  document.getElementById('stat-total-solved').innerText = userStats.solved;
  document.getElementById('stat-correct').innerText = userStats.correct;
  document.getElementById('stat-wrong').innerText = userStats.wrong;

  const pct = userStats.solved > 0 ? Math.round((userStats.correct / userStats.solved) * 100) : 0;
  document.getElementById('stat-accuracy').innerText = pct + '%';
}
